import { Group, Mesh, PlaneGeometry, MeshPhysicalNodeMaterial, MeshBasicNodeMaterial, Color, DoubleSide } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group: THREEGroup } = ctx.THREE ?? {};
  const GroupCtor = THREEGroup ?? Group;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  // ---- bridging idiom for text (list row: title + meta) ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const titleItem = items.find((i) => i.role === 'title' || i.role === 'headline');
  const metaItem = items.find((i) => i.role === 'meta' || i.role === 'caption' || i.role === 'subhead');

  const titleText = titleItem?.text ?? config.title ?? config.name ?? 'Collection Item';
  const metaText = metaItem?.text ?? config.meta ?? config.subtitle ?? '';

  const root = new GroupCtor();
  root.name = 'hub-collection-list-row';

  const inner = new GroupCtor();
  root.add(inner);

  const ROW_W = 3.2;
  const ROW_H = 0.7;

  // ---- row backing plate: machined-metal PBR card ----
  const geo = new PlaneGeometry(ROW_W, ROW_H);
  const mat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink),
    roughness: 0.56,
    metalness: 0.42,
    clearcoat: 0.18,
    clearcoatRoughness: 0.4,
    side: DoubleSide,
  });
  const plate = new Mesh(geo, mat);
  plate.position.z = 0;
  inner.add(plate);

  let mapTexture = null;
  ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
    tex.colorSpace = tex.colorSpace ?? undefined;
    mapTexture = tex;
    mat.map = tex;
    mat.needsUpdate = true;
  }).catch(() => {});

  // ---- divider: subtle horizontal line near bottom ----
  const dividerGeo = new PlaneGeometry(ROW_W * 0.92, 0.006);
  const dividerMat = new MeshBasicNodeMaterial({
    color: new Color(colors.paper),
    transparent: true,
    opacity: 0.16,
  });
  const divider = new Mesh(dividerGeo, dividerMat);
  divider.position.set(0, -ROW_H / 2 + 0.06, 0.02);
  inner.add(divider);

  // ---- accent focus edge (hidden by default) ----
  const edgeGeo = new PlaneGeometry(ROW_W + 0.04, ROW_H + 0.04);
  const edgeMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0.0,
    side: DoubleSide,
  });
  const edge = new Mesh(edgeGeo, edgeMat);
  edge.position.z = -0.01;
  inner.add(edge);

  // ---- title text (display / serif role) ----
  const titleMesh = ctx.fontAtlas.createText(String(titleText), {
    fontSize: 30,
    color: colors.paper,
    align: 'left',
    maxWidthPx: 380,
  });
  titleMesh.position.set(-ROW_W / 2 + 0.28, 0.08, 0.03);
  inner.add(titleMesh);

  // ---- meta text (mono caption role) ----
  let metaMesh = null;
  if (metaText) {
    metaMesh = ctx.fontAtlas.createText(String(metaText), {
      fontSize: 18,
      color: '#9aa1ad',
      align: 'right',
      maxWidthPx: 260,
      letterSpacingPx: 0.6,
    });
    metaMesh.position.set(ROW_W / 2 - 0.28, 0.08, 0.03);
    inner.add(metaMesh);
  }

  root.position.set(
    config.scenePosition?.x ?? 0,
    config.scenePosition?.y ?? 0,
    config.scenePosition?.z ?? 0
  );

  // ---- motion state ----
  const baseScale = 1;
  const hoverLift = 0.15; // subtle rise-in per spec
  let hoverTween = null;
  let pressTween = null;
  let edgeTween = null;
  let isPressed = false;

  const doHoverIn = () => {
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(inner.position, {
      y: hoverLift,
      duration: 0.35,
      ease: 'power2.out',
    });
    gsap.to(mat, { metalness: 0.5, duration: 0.35, ease: 'power2.out' });
  };

  const doHoverOut = () => {
    if (isPressed) return;
    if (hoverTween) hoverTween.kill();
    hoverTween = gsap.to(inner.position, {
      y: 0,
      duration: 0.35,
      ease: 'power2.out',
    });
    gsap.to(mat, { metalness: 0.42, duration: 0.35, ease: 'power2.out' });
  };

  const doPressDown = () => {
    isPressed = true;
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(inner.scale, {
      x: 0.97,
      y: 0.97,
      z: 1,
      duration: 0.12,
      ease: 'back.out(2)',
    });
  };

  const doPressUp = () => {
    isPressed = false;
    if (pressTween) pressTween.kill();
    pressTween = gsap.to(inner.scale, {
      x: baseScale,
      y: baseScale,
      z: 1,
      duration: 0.15,
      ease: 'power2.out',
    });
  };

  const doFocus = () => {
    if (edgeTween) edgeTween.kill();
    edgeTween = gsap.to(edgeMat, { opacity: 0.9, duration: 0.2, ease: 'power2.out' });
  };

  const doBlur = () => {
    if (edgeTween) edgeTween.kill();
    edgeTween = gsap.to(edgeMat, { opacity: 0.0, duration: 0.2, ease: 'power2.out' });
  };

  const doClick = () => {
    ctx.emit('hub-collection.select', {
      id: config.id ?? config.name ?? 'hub-collection-item',
      title: titleText,
    });
  };

  root.userData.handlers = {
    pointerenter: doHoverIn,
    pointerover: doHoverIn,
    pointerleave: doHoverOut,
    pointerout: doHoverOut,
    pointerdown: doPressDown,
    pointerup: doPressUp,
    focus: doFocus,
    blur: doBlur,
    click: doClick,
  };

  root.userData.cleanup = () => {
    if (hoverTween) hoverTween.kill();
    if (pressTween) pressTween.kill();
    if (edgeTween) edgeTween.kill();
    gsap.killTweensOf(inner.position);
    gsap.killTweensOf(inner.scale);
    gsap.killTweensOf(mat);
    gsap.killTweensOf(edgeMat);

    geo.dispose();
    mat.dispose();
    dividerGeo.dispose();
    dividerMat.dispose();
    edgeGeo.dispose();
    edgeMat.dispose();

    if (mapTexture && typeof mapTexture.dispose === 'function') {
      mapTexture.dispose();
    }

    if (titleMesh?.geometry) titleMesh.geometry.dispose?.();
    if (titleMesh?.material) titleMesh.material.dispose?.();
    if (metaMesh?.geometry) metaMesh.geometry.dispose?.();
    if (metaMesh?.material) metaMesh.material.dispose?.();

    inner.clear();
    root.clear();
  };

  return root;
}
